static const char *const *const tab[NLANG] = { s_en, s_de, s_es, s_it, s_fr, s_cs };

const char *L(int id)
{
    const char *s;
    if (id < 0 || id >= S_COUNT) return "?";
    s = tab[ui_lang >= 0 && ui_lang < NLANG ? ui_lang : 0][id];
    return s ? s : s_en[id];
}
